import { extent } from 'd3-array';
import { isNumber, isUndefined } from 'lodash-es';

import { isStacked } from './is-stacked.js';
import { ScaleMetadata } from './yAxis.js';
import { safeGet } from '../../core/functions/safe-get.js';
import { MinMaxConfig } from '../../core/types/min-max-config.js';
import { MinMax } from '../../core/types/min-max.js';
import { TimeseriesDatapoint } from '../../core/types/timeseries.js';
import { isBandDataPoint } from '../components/displays/shared/functions/get-timeseries-type.js';
import { TimeseriesBandDataPoint } from '../types/timeseries-band.js';
import { ChartVariant } from '../types/timeseries-props.js';
import {
  TimeseriesVariantSlotProps,
  WeakMapDatapoints,
  WeakMapSeries,
} from '../types/timeseries.js';

const getValueOrGap = (value: number | undefined, isGap: boolean) =>
  isGap ? 0 : value ?? 0;

const getYTimeSeries = (
  datapoint: TimeseriesDatapoint,
  datapointsMap: WeakMapDatapoints,
): number => {
  const metadata = safeGet(datapointsMap, datapoint);

  return getValueOrGap(metadata.value, metadata.isGap);
};
const getYBand0 = (
  datapoint: TimeseriesBandDataPoint,
  datapointsMap: WeakMapDatapoints,
): number => {
  const metadata = safeGet(datapointsMap, datapoint);

  return getValueOrGap(metadata.y0, metadata.isGap);
};
const getYBand1 = (
  datapoint: TimeseriesBandDataPoint,
  datapointsMap: WeakMapDatapoints,
): number => {
  const metadata = safeGet(datapointsMap, datapoint);

  return getValueOrGap(metadata.y1, metadata.isGap);
};

/**
 * Calculates the y scale-domain depending on given timeseries containing data-points.
 * Depending on the variant, the y-domain can be a min-max-range for non-stacked-visualizations
 * or a range from 0 to the max-sum of all data-points for a given series for stacked visualizations.
 *
 * It filters out of the calculation the gap datapoints.
 *
 * This function assumes that each series has a non-scarce data-points array, meaning that potential gaps
 * have been filled with gap-data-points before calling it.
 *
 * @param timeseries - The series that serves as base for calculating the domain of the datapoints.
 * @param variant - The Chart variant.
 * @param leftAxisMetadata - metadata set from previous geometries on the left axis
 * @param rightAxisMetadata - metadata set from previous geometries on the right axis
 * @param seriesMap - series metadata map
 * @param datapointsMap - data points metadata map
 * @returns the value-range for the given series depending on the chart-variant
 */
export function getYScaleDomains(
  timeseries: TimeseriesVariantSlotProps[],
  variant: ChartVariant,
  leftAxisMetadata: ScaleMetadata,
  rightAxisMetadata: ScaleMetadata,
  seriesMap: WeakMapSeries,
  datapointsMap: WeakMapDatapoints,
): ScaleMetadata[] {
  return getYAxisValueDomainsByUnit(
    timeseries,
    variant,
    leftAxisMetadata,
    rightAxisMetadata,
    seriesMap,
    datapointsMap,
  );
}

/**
 * Calculates the yAxis value-range depending on a given timeseries-array each containing data-points.
 * Depending on the passed chart-variant, the value-range can be:
 *  - non-stacked (e.g.: line): range from min value to max value across all datapoints for all series
 *  - stacked (e.g.: area): range from the sum of all min values to the sum of all max values across all datapoints grouped by timestamp
 *
 * @param series - The series that serves as base for calculating the value-range of the datapoints.
 * @param variant - The variant (or type) of the Chart, e.g. 'line', 'area', 'bar', etc.
 * @param leftAxisMetadata - metadata set from previous geometries on the left axis
 * @param rightAxisMetadata - metadata set from previous geometries on the right axis
 * @param seriesMap - series metadata map
 * @param datapointsMap - data points metadata map
 * @returns an object containing [key] as unit of the scale and value as the value-ranges for the given series depending on the chart-variant
 */
export function getYAxisValueDomainsByUnit(
  series: TimeseriesVariantSlotProps[],
  variant: ChartVariant,
  leftAxisMetadata: ScaleMetadata,
  rightAxisMetadata: ScaleMetadata,
  seriesMap: WeakMapSeries,
  datapointsMap: WeakMapDatapoints,
): ScaleMetadata[] {
  if (series.length === 0) {
    return [];
  }

  const otherGeometriesUnits = [
    leftAxisMetadata.unit,
    rightAxisMetadata.unit,
  ].filter((u) => u !== undefined);
  const seriesUnit = series.map((serie) => safeGet(seriesMap, serie).unit);
  const scaleUnits = [...new Set([...otherGeometriesUnits, ...seriesUnit])];

  return scaleUnits.map((unit) => {
    const filteredSeries = series.filter(
      (singleSeries) => safeGet(seriesMap, singleSeries).unit === unit,
    );

    if (isStacked(variant)) {
      return {
        ...getMinMax(
          filteredSeries.flatMap((singleSeries) =>
            singleSeries.datapoints.map((datapoint) => {
              const metadataDatatpoint = safeGet(datapointsMap, datapoint);

              if (metadataDatatpoint.isGap) {
                return 0;
              }

              return metadataDatatpoint.cumulativeValue ?? 0;
            }),
          ),
        ),
        unit,
      };
    }

    return {
      ...getSeriesMinMax(filteredSeries, datapointsMap),
      unit,
    };
  });
}

const getSeriesMinMax = (
  series: TimeseriesVariantSlotProps[],
  datapointsMap: WeakMapDatapoints,
): MinMax => {
  const datapoints = series.flatMap(
    (currentSeries) => currentSeries.datapoints,
  );

  if (datapoints.length && isBandDataPoint(datapoints[0])) {
    const [minY0 = 0, maxY0 = 0] = extent(
      datapoints as Iterable<TimeseriesBandDataPoint>,
      (dp) => getYBand0(dp, datapointsMap),
    );
    const [minY1 = 0, maxY1 = 0] = extent(
      datapoints as Iterable<TimeseriesBandDataPoint>,
      (dp) => getYBand1(dp, datapointsMap),
    );

    return { min: Math.min(minY0, minY1), max: Math.max(maxY0, maxY1) };
  }

  const [min = 0, max = 0] = extent(
    datapoints as Iterable<TimeseriesDatapoint>,
    (dp) => getYTimeSeries(dp, datapointsMap),
  );

  return { min, max };
};

const getMinMax = (values: number[]): MinMax => {
  let min = Infinity;
  let max = -Infinity;

  for (let i = 0; i < values.length; i++) {
    const value = values[i];
    if (value < min) {
      min = value;
    }
    if (value > max) {
      max = value;
    }
  }

  return {
    min: Math.min(0, min),
    max: Math.max(0, max),
  };
};

/**
 * Given the dataset domain and the user provided config,
 *
 * @param datasetDomain -
 * @param userConfig -
 * @returns the min-max of each axis (left and/or right)
 */
export const getYAxesMinMax = (
  datasetDomain: [MinMax, MinMax | undefined],
  userConfig: [MinMaxConfig | undefined, MinMaxConfig | undefined],
): [MinMax | undefined, MinMax | undefined] => {
  const [firstDatasetDomain, secondDatasetDomain] = datasetDomain;
  const [leftConfigDomain, rightConfigDomain] = userConfig;

  return [
    getYAxesMinMaxSide(firstDatasetDomain, leftConfigDomain),
    getYAxesMinMaxSide(secondDatasetDomain, rightConfigDomain),
  ];
};

const getYAxesMinMaxSide = (
  dataDomain: MinMax | undefined,
  configDomain: MinMaxConfig | undefined,
): MinMax | undefined => {
  if (isUndefined(dataDomain)) {
    return undefined;
  }

  const axisMinMax: MinMax = {
    min: dataDomain.min >= 0 ? 0 : dataDomain.min,
    max: dataDomain.max >= 0 ? dataDomain.max : 0,
  };
  const hasConfig = !isUndefined(configDomain);

  if (hasConfig) {
    if (isNumber(configDomain.min)) {
      axisMinMax.min = configDomain.min;
    } else if (configDomain.min === 'data-min') {
      axisMinMax.min = dataDomain.min;
    }

    if (isNumber(configDomain.max)) {
      axisMinMax.max = configDomain.max;
    } else if (configDomain.max === 'data-max') {
      axisMinMax.max = dataDomain.max;
    }
  }

  return axisMinMax;
};
